mapper.select:
/* PushTargetMapper.selectTbmEnteredTargets */
SELECT DISTINCT
       AT.CMPNY_CD    AS cmpnyCd
     , AT.USER_CD     AS userCd
  FROM TB_TBM_ATTENDANCE AT
 WHERE AT.SESSION_CD = #{sessionCd}
   AND AT.DEL_YN     = 'N'
   AND AT.ENTRY_AT IS NOT NULL
   AND NULLIF(TRIM(AT.USER_CD), '') IS NOT NULL
   AND EXISTS (
         SELECT 1
         FROM TB_TBM_SESSION S
         WHERE S.SESSION_CD = #{sessionCd}
           AND S.CMPNY_CD = #{hostCmpnyCd}
       )

/* PushTargetMapper.selectSiteRoleAdminUserCds */
SELECT DISTINCT U.USER_CD
  FROM TB_USER U
       INNER JOIN TB_USER_SITE_AUTH SA
          ON  U.CMPNY_CD = SA.CMPNY_CD
          AND U.USER_CD  = SA.USER_CD
          AND SA.SITE_CD = #{siteCd}
          AND SA.USE_YN  = 'Y'
 WHERE U.CMPNY_CD       = #{cmpnyCd}
   AND U.USE_YN         = 'Y'
   AND U.ACCOUNT_STATUS = '01'
   AND U.AUTH_CD IN

           #{authCd}
